const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const productCategory=p=>p.category||productInfo(p.image).category;
let shopCategory='전체',replyDrafts={},studentSearch='',jobDraft=null,jobPicked=null;
function productInfo(id){id=Number(id);if([1,2,4,5].includes(id))id=0;return PRODUCT_CATALOG.find(p=>p.id===id)||{id:3,label:'간식',category:'간식',sprite:3};}
function productPicker(value){const chosen=productInfo(value).id;return `<fieldset class="image-picker"><legend>상품 그림</legend>${PRODUCT_CATALOG.map(p=>`<label class="image-choice"><input type="radio" name="image" value="${p.id}" ${chosen===p.id?'checked':''} required>${productArt(p.id)}<span>${E(p.label)}</span></label>`).join('')}</fieldset>`;}
let state=null,token=sessionStorage.getItem('sebit-token'),page='home',selected=new Set(),busy=false,lastActivity=Date.now(),lastTouch=0,activityDate='',activityKind='morning',selectedThread=null,category=null,historyStudent=null;
let messageDraft={title:'',body:''},historyCurrency='lumen';
if(token&&performance.getEntriesByType('navigation')[0]?.type!=='reload'){token=null;sessionStorage.removeItem('sebit-token');}
const studentMenus=[['home','⌂','홈'],['pocket','▣','주머니'],['morning','☀','아침 활동'],['reading','▤','독서'],['jobs','⚑','직업'],['quests','✦','퀘스트'],['shop','▧','상점'],['bank','▥','은행'],['thermo','♧','온도계'],['laws','⚖','학급 법'],['citizen','♛','모범시민'],['messages','✉','선생님께 메시지']];
const teacherMenus=[['home','⌂','홈'],['students','♙','학생 관리'],['points','✧','점수 관리'],['activities','☀','활동 관리'],['jobs','⚑','직업 관리'],['quests','✦','퀘스트 관리'],['shop','▧','상점 관리'],['bank','▥','은행 관리'],['thermo','♧','온도계 관리'],['penalties','⚖','벌점 관리'],['laws','▤','학급 법 관리'],['messages','✉','메시지'],['schedule','▦','일정·급식'],['settings','⚙','학급 설정']];
const T=()=>state?.actor==='teacher', me=()=>state?.me, today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(state?.serverTime||Date.now())), fmt=t=>new Date(t).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}), money=n=>Number(n).toLocaleString('ko-KR'), name=id=>state.students.find(p=>p.id===id)?.name||(id===state.actor?me()?.name:'전출 학생'), find=(list,id)=>list.find(x=>x.id===id), active=()=>state.students.filter(p=>p.active), mine=list=>list.filter(x=>x.student===state.actor), atRank=p=>state.ranks.reduce((v,r,i)=>p.xp>=r.xp?i:v,0);
function btn(label,action,id='',cls=''){return `<button class="${cls}" data-action="${action}" data-id="${E(id)}">${label}</button>`}function empty(text){return `<div class="empty-state"><div class="symbol">✧</div>${E(text)}</div>`}function card(title,body,cls=''){return `<section class="card ${cls}"><h2>${title}</h2>${body}</section>`}function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('아직 기록이 없어요.')}function field(label,name,type='text',value='',extra=''){return `<label>${label}</label><input name="${name}" type="${type}" value="${E(value)}" ${extra}>`}function area(label,name,value=''){return `<label>${label}</label><textarea name="${name}">${E(value)}</textarea>`}function select(label,name,options,value=''){return `<label>${label}</label><select name="${name}">${options.map(([v,l])=>`<option value="${E(v)}" ${v==value?'selected':''}>${E(l)}</option>`).join('')}</select>`}function rewardFields(v=[10,5]){return `<div class="grid cols2">${field('루멘','lumen','number',v[0],'min="0" required')}${field('XP','xp','number',v[1],'min="0" required')}</div>`}function numberFields(f){return [+f.lumen,+f.xp]}function selector(recorded=null){return `<div class="toolbar">${btn('전체 선택','selectAll','','small')}${btn('선택 해제','clearSelect','','small')}<span class="muted">${selected.size}명 선택</span><input id="student-search" type="search" aria-label="학생 이름 검색" placeholder="이름 · 번호 검색" value="${E(studentSearch)}"></div><div class="select-grid student-cards">${active().map(p=>{const done=recorded?.has(p.id);return `<button class="student-select ${selected.has(p.id)?'selected':''}" data-action="select" data-id="${p.id}" data-student-label="${E(p.name+' '+p.number+' '+p.login)}" aria-pressed="${selected.has(p.id)}" ${studentSearch&&!(`${p.name} ${p.number} ${p.login}`).includes(studentSearch)?'hidden':''}><div class="avatar ${recorded&&!done?'inactive':''}">${creature(p)}</div><strong>${E(p.name)}</strong><span class="time">${p.number}번 · ${E(p.login)}</span>${recorded?`<span class="activity-status ${done?'done':''}">${done?'완료 ✓':'미완료'}</span>`:`<span class="student-balances"><b>${money(p.lumen)} 루멘</b><span>${money(p.xp)} XP</span></span>`}<span class="selection-mark" aria-hidden="true">${selected.has(p.id)?'✓':'＋'}</span></button>`}).join('')}</div>`}

async function api(path,data){return SEBIT_TRANSPORT.request(path,data,token);}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
async function command(cmd,data={},message='저장했어요.'){if(busy)return;const ownerToken=token;busy=true;document.body.setAttribute('aria-busy','true');const requestId=crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');try{let r;try{r=await api('command',{command:cmd,data,requestId})}catch(e){if(e instanceof TypeError)r=await api('command',{command:cmd,data,requestId});else throw e;}if(token!==ownerToken)return;if(r.logout){logout(false);return}await refresh();if(token!==ownerToken)return;if(message)toast(message);return true}catch(e){toast(e.message)}finally{busy=false;document.body.removeAttribute('aria-busy')}}
function modal(title,body,submit='저장',wide=false){const d=$('#dialog');if(d.open)d.close();d.innerHTML=`<form id="modal-form"><h2>${title}</h2>${body}<div class="error" id="modal-error"></div><div class="actions"><button type="button" id="modal-cancel">닫기</button>${submit?`<button class="primary" type="submit">${submit}</button>`:''}</div></form>`;d.style.width=wide?'min(900px,94vw)':'';d.showModal();return new Promise(resolve=>{let done=false;function end(v){if(done)return;done=true;d.close();resolve(v)}$('#modal-cancel').onclick=()=>end(null);d.oncancel=()=>end(null);$('#modal-form').onsubmit=e=>{e.preventDefault();end(Object.fromEntries(new FormData(e.target)))};});}
async function confirmBox(title,body){return !!await modal(title,body,'확인')}
async function logout(remote=true){if(remote&&token)api('logout',{}).catch(()=>{});token=null;state=null;sessionStorage.removeItem('sebit-token');selected.clear();selectedThread=null;historyStudent=null;messageDraft={title:'',body:''};replyDrafts={};shopCategory='전체';$('#dialog').close();$('#app').innerHTML='<div class="loading">로그아웃했어요.</div>';await start();}
async function start(){try{if(token){await refresh();return}const status=await api('status');$('#app').innerHTML=`<div class="card auth"><div class="brand">SEBIT<span>✦</span></div><h1>${status.configured?'함께 자라는 교실':'우리 학급 시작하기'}</h1><p class="subhead" style="text-align:center">${E(status.className||'새로운 모험을 준비해요')}</p><form id="auth-form">${status.configured?select('로그인','type',[['student','학생'],['teacher','교사']])+field('학생 아이디','id','text','','placeholder="S01" autocomplete="username"'):field('학급 이름','className','text','','required')+field('학급 개설 코드','setupKey','password','','required autocomplete="off"')}${field(status.configured?'PIN / 비밀번호':'교사 비밀번호 (8자 이상)','password','password','','required autocomplete="current-password"')}<div class="error" id="auth-error"></div><button class="primary" type="submit">${status.configured?'로그인':'학급 만들기'}</button></form><p class="hint">${status.configured?'학생은 개인 아이디와 PIN으로 접속해요.':'배포할 때 정한 개설 코드로 선생님이 학급을 만들어 주세요.'}</p></div>`;const type=$('[name=type]');if(type)type.onchange=()=>{$('[name=id]').disabled=type.value==='teacher';$('[name=id]').value=type.value==='teacher'?'teacher':''};$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{if(!status.configured)await api('setup',f);const r=await api('login',{id:status.configured?(f.type==='teacher'?'teacher':f.id):'teacher',password:f.password});token=r.token;sessionStorage.setItem('sebit-token',token);lastActivity=Date.now();page='home';await refresh()}catch(err){$('#auth-error').textContent=err.message}}}catch(e){$('#app').innerHTML=empty(e.message)}}
async function refresh(renderNow=true){const requestedToken=token;try{const next=await api('state');if(!token||token!==requestedToken)return;state=next;if(renderNow)render();if(!T()&&me().mustChange&&!$('#dialog').open){const f=await modal('나만의 PIN을 정해요',`<p>임시 PIN 대신 사용할 숫자 4~8자리를 입력해 주세요.</p>${field('새 PIN','pin','password','','required minlength="4" maxlength="8" pattern="[0-9]{4,8}"')}`,'PIN 변경');if(f)await command('pin',f);else await logout();}}catch(e){if(!token||token!==requestedToken)return;toast(e.message);if(/로그인|로그아웃|접속|자료를 찾/.test(e.message))await logout(false);}}
function badgeFor(key){let n=0;if(key==='messages')n=T()?state.threads.filter(t=>!t.closed&&t.lastBy!=='teacher').length:state.notifications.filter(n=>n.menu==='messages'&&!n.read).length;if(key==='quests'&&T())n=state.applications.filter(a=>a.status==='pending').length;if(!T()&&key==='quests')n=state.notifications.filter(x=>x.menu==='quests'&&!x.read).length;if(!T()&&key==='pocket')n=mine(state.items).filter(i=>i.status==='pending').length;if(!T()&&['morning','reading'].includes(key)&&!state.closures[key+':'+today()]&&!state.activities.some(r=>r.kind===key&&r.date===today()))return '<span class="badge">미완료</span>';if(key==='delivery')n=state.items.filter(i=>i.status==='pending').length;return n?`<span class="badge">${n}</span>`:''}
function questIcon(){return `<img class="quest-icon" src="./assets/quest-scroll.svg" alt="퀘스트 두루마리">`}
function pageDecor(){const info={reading:['별빛 도서관','책 속에서 발견하는 새로운 세상','book'],bank:['빛을 모으는 은행','차곡차곡 쌓이는 나의 노력','bank'],shop:['마법 상점','노력의 반짝임이 특별한 물건으로','shop'],messages:['마음을 담은 쪽지','작은 봉투에 담는 나의 이야기','mail'],quests:['모험의 퀘스트','새로운 도전이 기다리고 있어요','scroll'],jobs:['우리 반 직업','함께 만드는 멋진 교실','flag'],activities:['오늘의 발자취','작은 실천이 모여 큰 성장으로','sun'],points:['성장의 기록','아이들의 노력이 빛나는 순간','star'],thermo:['마음의 온도계','함께 모은 마음으로 따뜻해지는 교실','heart']};const i=info[page];return i?`<section class="page-scene scene-${i[2]}" aria-label="${i[0]}"><div><div class="eyebrow">${T()?'숲속의 교실':'별빛의 교실'}</div><h2>${i[0]}</h2><p>${i[1]}</p></div><img src="./assets/decor-${i[2]}.svg" alt="" aria-hidden="true"></section>`:''}
function donationHistory(){const donations=state.donations.filter(d=>d.round===state.thermo.round).slice().reverse();const totals={};donations.forEach(d=>totals[d.student]=(totals[d.student]||0)+d.amount);return card(T()?'이번 회차 기부 내역':'나의 기부 내역',table(['학생','기부한 루멘','날짜 · 시각'],donations.map(d=>[E(name(d.student)),money(d.amount)+' 루멘',d.time?fmt(d.time):d.date+' (시각 기록 없음)'])))+(T()?card('학생별 누적 기부',table(['학생','이번 회차 누적'],Object.entries(totals).sort((a,b)=>b[1]-a[1]).map(([id,amount])=>[E(name(id)),money(amount)+' 루멘']))):'')}
function jobBoard(){return `<div id="job-board">${jobBoardBody()}</div>`}
function jobBoardBody(){return `<p class="hint">학생 이름을 직업 칸으로 끌어 놓으세요. 터치할 때는 이름을 누른 뒤 직업 칸의 배치 버튼을 누르세요. 한 직업에 여러 명을 배치할 수 있어요.</p><section class="job-pool job-zone" data-job-zone=""><h3>미배정 학생</h3><div class="job-names">${active().filter(p=>!jobDraft[p.id]).map(jobChip).join('')||'<span class="muted">모두 배치했어요.</span>'}</div><button type="button" data-action="jobDrop" data-id="" ${jobPicked?'':'disabled'}>선택 학생 배치 해제</button></section><div class="grid cols3 section">${state.jobs.filter(j=>j.active).map(j=>`<section class="job-zone" data-job-zone="${E(j.id)}"><h3>⚑ ${E(j.name)}</h3><p class="time">${j.reward[0]}루멘 · ${j.reward[1]}XP / 수행일</p><div class="job-names">${active().filter(p=>jobDraft[p.id]===j.id).map(jobChip).join('')||'<span class="muted">이곳으로 이름을 끌어 놓으세요.</span>'}</div><button type="button" data-action="jobDrop" data-id="${E(j.id)}" ${jobPicked?'':'disabled'}>선택 학생 배치</button></section>`).join('')}</div>${active().map(p=>`<input type="hidden" name="${E(p.id)}" value="${E(jobDraft[p.id]||'')}">`).join('')}`}
function jobChip(p){return `<button type="button" draggable="true" class="job-chip ${jobPicked===p.id?'picked':''}" data-drag-student="${E(p.id)}" data-action="jobPick" data-id="${E(p.id)}" aria-pressed="${jobPicked===p.id}">${p.number} ${E(p.name)}</button>`}
function paintJobBoard(){const board=$('#job-board');if(board&&jobDraft)board.innerHTML=jobBoardBody()}
function placeJob(job,student=jobPicked){if(!jobDraft||!student||!active().some(p=>p.id===student))return;if(job&&!state.jobs.some(j=>j.active&&j.id===job))return;if(job)jobDraft[student]=job;else delete jobDraft[student];jobPicked=null;paintJobBoard()}
document.addEventListener('dragstart',e=>{const chip=e.target.closest('[data-drag-student]');if(!chip||!jobDraft)return;e.dataTransfer.setData('text/plain',chip.dataset.dragStudent);e.dataTransfer.effectAllowed='move'});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-job-zone]');if(zone&&jobDraft){e.preventDefault();e.dataTransfer.dropEffect='move';zone.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-job-zone]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-job-zone]');if(zone&&jobDraft){e.preventDefault();placeJob(zone.dataset.jobZone,e.dataTransfer.getData('text/plain'))}});
function render(){if(!state)return;document.body.setAttribute('data-theme',T()?'forest':'cosmos');document.body.setAttribute('data-page',page);const menus=[...(T()?teacherMenus:studentMenus)];if(!T()&&state.myRole==='merchant')menus.push(['delivery','▣','상인 지급 목록']);if(!T()&&state.myRole==='ranger')menus.push(['report','⚖','위반 등록']);const title=menus.find(m=>m[0]===page)?.[2]||'변동 내역';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">SEBIT<span>✦</span></div><div class="tagline">함께 자라는 우리 교실</div><nav class="nav">${menus.map(([id,icon,label])=>`<button data-nav="${id}" class="${page===id?'active':''}"><span class="icon">${icon}</span>${label}${badgeFor(id)}</button>`).join('')}</nav></aside><main><header class="topbar"><div><div class="eyebrow">${E(state.className)} · ${T()?'TEACHER':'MY CLASSROOM'}</div><h1>${page==='home'?(T()?'오늘의 학급':E(me().name)+'의 하루'):title}</h1><p class="subhead">${page==='home'?'작은 하루가 모여, 더 큰 나로 자라요.':today()+' · 함께 만드는 우리 교실'}</p></div><div class="top-actions">${T()?`<button class="pill" data-action="toggleOpen">학생 접속 ${state.opened?'열림':'닫힘'}</button>`:''}<button class="mobile-menu" data-action="menu">☰</button>${!T()?btn('PIN 변경','changePin','','small ghost'):''}${btn('로그아웃','logout','','small ghost')}</div></header><div id="content">${pageDecor()}${content()}</div></main></div>`;}
function creature(p,cls=''){let ch=p.character||'default';let col=0,row=0;if(ch!=='default'){[col,row]=ch.split('-').map(Number);row+=1;}return `<div class="creature ${cls}" style="background-position:${col*25}% ${row*25}%" role="img" aria-label="${ch==='default'?'공통 기본 알':['용','그리핀','불사조','바다 괴수'][row-1]+' '+(col+1)+'등급'}"></div>`;}
function productArt(id,cls=''){const p=productInfo(id);if(p.src)return `<img class="product-photo ${cls}" src="${p.src}" alt="${E(p.label)}" loading="lazy" decoding="async">`;return `<span class="product-art ${cls}" style="background-position:${(p.sprite%4)*100/3}% ${Math.floor(p.sprite/4)*100}%" role="img" aria-label="${E(p.label)}"></span>`;}
function pocket(compact=false){let items=mine(state.items).filter(i=>i.status!=='delivered');return `<div class="slots">${Array.from({length:6},(_,n)=>{let i=items[n];return i?`<div class="slot">${productArt(i.image)}<strong>${E(i.name)}</strong>${i.status==='pending'?`<span class="time">지급 대기 · ${Math.max(1,Math.ceil((i.until-state.serverTime)/60000))}분</span>`:btn('지급 요청','request',i.id,'small')}</div>`:'<div class="slot empty">＋</div>'}).join('')}</div>`}
function notifications(){return `<div class="flex between"><h2>내 알림</h2>${btn('모두 읽음','read','','small ghost')}</div>${mine(state.notifications).slice(-10).reverse().map(n=>`<div class="notification ${n.read?'':'unread'}"><button data-nav="${n.menu}">${E(n.body)}<div class="time">${fmt(n.time)}</div></button></div>`).join('')||empty('새 알림이 없어요.')}`}
function home(){if(T()){const pending=state.applications.filter(a=>a.status==='pending').length,threads=state.threads.filter(t=>!t.closed&&t.lastBy!=='teacher').length;return `${card('처리할 일',`<div class="grid cols4">${[['quests','✦','퀘스트 승인',pending+'건'],['activities','☀','활동 마감','오늘 기록 확인'],['jobs','⚑','직업 정산',state.jobPeriods.some(p=>p.status==='ended')?'정산 대기':'직업 현황'],['messages','✉','새 메시지',threads+'건']].map(([p,i,t,v])=>`<button class="tile" data-nav="${p}"><div class="symbol mint">${i}</div><strong>${t}</strong><div class="large">${v}</div></button>`).join('')}</div>`)}<div class="grid cols3 section">${card('학급 온도계',thermoSummary()+btn('온도계 관리','go','thermo','small'))}${card('모범시민',citizenSummary()+btn('벌점 관리','go','penalties','small'))}${card('우리 반 학생',`<div class="large">${active().length}<span class="muted" style="font-size:16px">명</span></div><p>현재 활동 중인 학생</p><div class="section">${btn('명단 관리','go','students','small')}${btn('점수 관리','go','points','small')}</div>`)}</div><div class="grid cols2 section">${scheduleCards()}${card('최근 위반 현황',table(['학생','내용','상태'],state.violations.slice(-5).reverse().map(v=>[E(name(v.student)),E(v.name),v.cancelled?'취소':'등록'])))}</div>`}let p=me(),rank=atRank(p),next=state.ranks[rank+1],base=state.ranks[rank].xp,percent=next?Math.min(100,(p.xp-base)/(next.xp-base)*100):100;
const quests=state.quests.filter(q=>q.status==='published'&&q.start<=today()&&q.end>=today()&&!state.applications.some(a=>a.quest===q.id&&a.status==='approved')).slice(0,2);
return `<div class="grid student-home"><div class="stack"><section class="card hero companion-hero"><div class="flex between"><h2>✦ 나의 캐릭터</h2><span class="pill">성장 ${rank+1}단계</span></div><div class="companion-stage"><button class="character-open" data-action="characters" aria-label="현재 등급 캐릭터 선택">${creature(p)}</button></div><h3>${E(state.ranks[rank].name)}</h3><div class="grid cols2 home-metrics"><button data-action="go" data-id="history"><span>보유 루멘</span><strong>${money(p.lumen)}</strong></button><button data-action="go" data-id="xpHistory"><span>누적 XP</span><strong>${money(p.xp)}</strong></button></div><p>${next?'다음 성장까지 '+money(next.xp-p.xp)+' XP':'가장 높은 등급에 도달했어요!'}</p><div class="progress"><i style="width:${percent}%"></i></div>${btn('캐릭터 선택','characters','','small')}</section>${card('라이트 포켓 <span class="time">'+mine(state.items).filter(i=>i.status!=='delivered').length+' / 6칸</span>',pocket(true))}</div><div class="stack">${card('☀ 오늘의 활동',`<div class="stack">${[['morning','☀','아침 활동'],['reading','▤','독서'],['jobs','⚑','직업 수행']].map(([id,icon,label])=>`<button class="tile activity-tile" data-nav="${id}"><span class="symbol">${icon}</span><div><strong>${label}</strong><p>${id==='jobs'?(state.jobRecords.some(r=>r.date===today())?'완료했어요 ✓':'오늘의 직업 확인'):state.activities.some(r=>r.kind===id&&r.date===today())?'기록했어요 ✓':'기록하러 가기 →'}</p></div></button>`).join('')}</div>`)}${card('진행 중인 퀘스트',quests.map(q=>`<button class="home-quest" data-nav="quests">${questIcon()}<div><strong>${E(q.name)}</strong><p>${q.reward[0]}루멘 · ${q.reward[1]}XP</p></div></button>`).join('')||empty('새로운 퀘스트를 기다리고 있어요.'))}${card('✉ 새로 온 쪽지',`<p>${state.notifications.filter(n=>n.menu==='messages'&&!n.read).length?'선생님이 보낸 새 쪽지가 있어요.':'선생님과 마음을 나눠요.'}</p><div class="section">${btn('쪽지 확인하기','go','messages','primary')}</div>`)}<section class="card">${notifications()}</section>${scheduleCards()}</div></div>`}

function scheduleCards(){let v=state.schedule[today()]||{};return card('오늘의 일정 · 급식',`<div class="grid cols2"><div><h3 class="mint">일정</h3><p class="line-text">${E(v.events||'등록된 일정이 없어요.')}</p></div><div><h3 class="gold">급식</h3><p class="line-text">${E(v.meal||'등록된 급식이 없어요.')}</p></div></div>`)}
function historyTabs(){return `<div class="tabs section">${btn('루멘','historyCurrency','lumen',historyCurrency==='lumen'?'active':'')}${btn('XP','historyCurrency','xp',historyCurrency==='xp'?'active':'')}</div>`;}
function ledger(sid){let rows=state.ledger.filter(r=>(!sid||r.student===sid)&&(!sid||r[historyCurrency]!==0)).slice(-(T()?30:10)).reverse();return table(['시각','학생 / 사유','루멘','XP','처리'],rows.map(r=>[fmt(r.time),`${E(name(r.student))}<div class="muted">${E(r.reason)}</div>`,`${r.lumen>0?'+':''}${r.lumen}<div class="time">잔액 ${r.balance}</div>`,`${r.xp>0?'+':''}${r.xp}<div class="time">누적 ${r.xpBalance}</div>`,r.cancelled?`<span class="muted">취소됨</span>${T()&&r.kind==='reward'?btn('재지급','repay',r.id,'small'):''}`:T()&&['manual','reward','penalty'].includes(r.kind)?btn('취소','reverse',r.id,'small danger'):'—']))}
function studentsPage(){return card('학생 명단',`<div class="toolbar">${btn('명단 붙여넣기','roster','','primary')}${btn('한 명 추가','addStudent')}</div><p class="hint">번호는 전출 후에도 재사용하지 않아요. 임시 PIN은 학생에게 개별 안내해 주세요.</p>${table(['번호 / ID','이름','루멘 / XP','상태','임시 PIN','관리'],state.students.map(p=>[`${p.number} / ${E(p.login)}`,btn(E(p.name),'studentDetail',p.id,'ghost small'),`${p.lumen} / ${p.xp}`,p.active?'활동 중':'전출',p.mustChange?E(p.tempPin||'재발급 필요'):'변경 완료',btn('수정','editStudent',p.id,'small')+' '+btn('PIN 초기화','resetPin',p.id,'small')]))}`)}
function pointsPage(){return card('학생을 선택해 주세요',selector()+`<div class="section">${btn('지급 · 차감','points','','primary')}</div>`)+card('최근 변동 내역',`<p class="hint">학생별 내역은 학생 이름을 눌러 확인할 수 있어요.</p>${ledger()}`)}
function activityPage(kind){let rows=state.activities.filter(r=>r.kind===kind).slice(-30).reverse(),closed=state.closures[kind+':'+today()];return card(kind==='morning'?'오늘의 아침 활동':'오늘의 독서',`<p>${closed?'오늘 활동이 마감되었어요. 수정은 선생님께 문의해 주세요.':kind==='morning'?'활동을 수행한 뒤 완료를 눌러 주세요.':'오늘 읽은 책을 최대 3건까지 기록할 수 있어요.'}</p><div class="section">${!closed?btn(kind==='morning'?'수행 완료':'독서 기록하기','record',kind,'primary'):''}</div>`)+card('나의 기록',table(kind==='morning'?['날짜','내용']:['날짜','책','쪽','읽은 쪽수'],rows.map(r=>kind==='morning'?[r.date,'수행 완료']:[r.date,E(r.title),r.start+'~'+r.end,r.end-r.start+1])))}
function activitiesPage(){let d=activityDate||today(),kind=activityKind,records=state.activities.filter(r=>r.date===d&&r.kind===kind);return card('활동 확인 · 마감',`<div class="toolbar"><input type="date" id="activity-date" value="${d}" max="${today()}"><select id="activity-kind"><option value="morning" ${kind==='morning'?'selected':''}>아침 활동</option><option value="reading" ${kind==='reading'?'selected':''}>독서</option></select>${btn('기록 학생 선택','selectRecorded','','small')}${btn('누락 기록 추가','teacherRecord','','small')}</div><p class="hint">기록을 근거로 대상을 선택하세요. 이미 유효하게 지급된 학생은 중복 지급하지 않아요.</p>${selector(new Set(records.map(r=>r.student)))}<div class="section">${btn('마감 및 보상 지급','closeActivity','','primary')}</div>`)+card('해당 날짜 기록',table(['학생','기록','관리'],records.map(r=>[E(name(r.student)),r.kind==='reading'?E(r.title)+` (${r.start}~${r.end}쪽)`:'수행 완료',r.kind==='reading'?btn('수정','editReading',r.id,'small'):'—'])))}
function shopPage(){const products=state.products.filter(p=>(T()||p.active)&&(shopCategory==='전체'||productCategory(p)===shopCategory));return `${T()?`<div class="toolbar">${btn('상품 추가','editProduct','','primary')}${btn('지급 목록','go','delivery')}${btn('완료된 지급','delivered')}</div><p class="hint">기본 간식은 준비 상태예요. 상품을 눌러 가격·재고를 확인한 뒤 판매를 시작하세요.</p>`:'<div class="note">구매 후 환불할 수 없어요. 주머니에서 지급을 요청해 주세요. 물건 하나당 한 칸이에요.</div>'}<div class="tabs section" aria-label="상품 분류">${['전체','간식','문구','쿠폰','특별'].map(c=>btn(c,'shopCategory',c,shopCategory===c?'active':'')).join('')}</div><div class="grid cols3 shop-grid">${products.map(p=>{let discount=state.discounts[today()]===p.id&&p.active,price=discount?Math.floor((p.price*85+50)/100):p.price;return `<section class="card product ${!p.active?'preparing':''}">${discount?'<span class="discount">오늘의 15% 할인</span>':''}<div class="art">${productArt(p.image,'big')}</div><span class="time">${E(productCategory(p))} · ${!p.active?'판매 준비':p.stock?'판매 중':'품절'}</span><h3>${E(p.name)}</h3>${p.description?`<p class="product-description">${E(p.description)}</p>`:''}<p>재고 ${p.stock}개</p><div class="price">${!p.active&&p.price===0?'가격 확인 필요':money(price)+' 루멘'}${discount?`<del>${p.price}</del>`:''}</div>${T()?btn('상품 수정','editProduct',p.id):`<button class="primary" data-action="buy" data-id="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'구매하기':'품절'}</button>`}</section>`}).join('')||empty(T()?'이 분류에 상품이 없어요. 상품을 추가해 주세요.':'아직 판매 중인 상품이 없어요.')}</div>`}

function deliveryPage(){return card('지급 대기 목록',table(['학생','상품','요청 만료','처리'],state.items.filter(i=>i.status==='pending').map(i=>[E(name(i.student)),productArt(i.image)+' '+E(i.name),fmt(i.until),btn('지급 완료','deliver',i.id,'primary small')])))}
function bankPage(){let deposits=state.deposits.filter(d=>d.status==='active');return card('10일 예금 · 이자 3%',`${T()?'<p>진행 중인 예금과 최근 30건의 은행 기록이에요.</p>':'<p>100루멘 단위로 한 개의 예금을 가입할 수 있어요. 만기에 원금과 이자가 자동 지급돼요.</p><div class="section">'+btn('예금 가입','deposit','','primary')+'</div>'}${table(['학생','원금','만기','관리'],deposits.map(d=>[E(name(d.student)),money(d.amount)+' 루멘',fmt(d.due),btn('중도 해지','withdraw',d.id,'small')]))}`)+card('은행 내역',table(['시각','학생','유형','원금','이자'],state.bankEvents.slice(-30).reverse().map(d=>[fmt(d.time),E(name(d.student)),d.type,money(d.amount),d.interest])))}
function thermoSummary(){let total=state.thermo.total,next=Math.min(10000,(Math.floor(total/2000)+1)*2000);return `<div class="thermo-number">${(total/100).toFixed(1)}<span style="font-size:26px">°C</span></div><div class="progress"><i style="width:${total/100}%"></i></div><p>누적 ${money(total)}루멘</p><p class="hint">${total===10000?'최종 목표 달성!':`다음 ${next/100}°C까지 ${money(next-total)}루멘`}</p>`}
function thermoPage(){return card('우리의 마음을 모아요',thermoSummary()+`<div class="section">${T()?btn('이벤트 설정','thermoEvents')+' '+btn('새 회차 시작','thermoReset','','danger'):state.thermo.total<10000?btn('기부하기','donate','','primary'):''}</div><div class="grid cols4 section">${state.thermo.events.map((e,i)=>`<div class="stage ${state.thermo.total>=(i+1)*2000?'reached':''}"><h3>${(i+1)*20}°C</h3><p>${E(e)}</p><div class="section">${state.thermo.done.includes(i+1)?'실행 완료 ✓':T()&&state.thermo.total>=(i+1)*2000?btn('실행 완료','thermoDone',i+1,'small'):state.thermo.total>=(i+1)*2000?'목표 달성':'도전 중'}</div></div>`).join('')}</div>`)+donationHistory()}
function jobsPage(){let p=[...state.jobPeriods].reverse().find(p=>p.status!=='paid');if(T())return `<div class="toolbar">${btn('직업 추가','editJob','','primary')}${!p?btn('배정 · 기간 시작','jobStart'):p.status==='active'?btn('기간 종료','jobEnd',p.id):btn('확인 후 정산','jobPay',p.id,'primary')}</div>${p?card('이번 직업 기간 · '+(p.status==='active'?'진행 중':'정산 대기'),table(['학생','직업','원본 수행일','인정일','관리'],Object.entries(p.assignments).map(([sid,jid])=>{let days=state.jobRecords.filter(r=>r.period===p.id&&r.student===sid).map(r=>r.date);return [E(name(sid)),E(p.jobs[jid].name),days.join(', ')||'없음',(p.adjustments[sid]||days).length+'일',p.status==='ended'?btn('일수 정정','jobAdjust',sid,'small'):btn('오배정 정정','jobAssignment',sid,'small')]}))):''}<div class="grid cols3 section">${state.jobs.map(j=>card(E(j.name),`<p>${j.reward[0]}루멘 · ${j.reward[1]}XP / 수행일</p><p>${E(j.checklist.join(' · '))}</p><div class="section">${btn('수정','editJob',j.id,'small')} ${j.active?'':'비활성'}</div>`)).join('')}</div>`;let jid=p?.assignments[state.actor],job=jid?p.jobs[jid]:null;return job?card(E(job.name),`<p>수행일마다 ${job.reward[0]}루멘 · ${job.reward[1]}XP, 교사 정산 후 지급</p><form id="job-complete">${job.checklist.map((x,i)=>`<div class="check-row"><input id="check-${i}" type="checkbox" name="check" value="${i}" required><label for="check-${i}">${E(x)}</label></div>`).join('')}${area('메모 (선택)','memo')}<div class="section"><button class="primary" type="submit" ${p.status!=='active'||state.jobRecords.some(r=>r.period===p.id&&r.date===today())?'disabled':''}>오늘 수행 완료</button></div></form>`)+card('수행 기록',table(['날짜','메모'],state.jobRecords.slice(-30).reverse().map(r=>[r.date,E(r.memo)]))):empty('진행 중인 배정 직업이 없어요.')}
function questsPage(){let qs=state.quests.filter(q=>T()||q.status==='published');return `${T()?`<div class="toolbar">${btn('퀘스트 만들기','editQuest','','primary')}</div>`:''}<div class="grid cols3">${qs.map(q=>{let app=[...state.applications].reverse().find(a=>a.quest===q.id&&a.student===state.actor);return card(`${questIcon()}<span>${E(q.name)}</span>`,`<p class="line-text">${E(q.description)}</p><p class="hint">${q.start} ~ ${q.end}</p><p class="gold section">${q.reward[0]}루멘 · ${q.reward[1]}XP</p><div class="section">${T()?`<span class="pill">${E(q.status)}</span><div class="flex section">${btn('복사','questCopy',q.id,'small')}${btn('종료','questEnd',q.id,'small')}${btn('숨김','questHide',q.id,'small')}${btn('삭제','questDelete',q.id,'small')}${btn(q.status==='draft'?'편집 · 공개':'내용 수정','editQuest',q.id,'small')}</div>`:app?.status==='approved'?'보상 지급 완료 ✓':app?.status==='pending'?'확인 대기 중':`${app?.status==='rejected'?'<p class="danger">'+E(app.reason)+'</p>':''}${btn('완료 신청','applyQuest',q.id,'primary')}`}</div>`)}).join('')||empty('등록된 퀘스트가 없어요.')}</div>${T()?card('완료 신청',table(['학생','퀘스트','상태','처리'],state.applications.slice().reverse().map(a=>[E(name(a.student)),E(find(state.quests,a.quest)?.name),E(a.status),a.status==='pending'?btn('승인','approveQuest',a.id,'small primary')+' '+btn('반려','rejectQuest',a.id,'small'):'—']))):''}`}
function lawsPage(report=false){let cats=state.categories,chosen=category||cats[0]?.id,rr=state.rules.filter(r=>r.category===chosen);return `${T()?`<div class="toolbar">${btn('카테고리 추가','editCategory','','primary')}${chosen?btn('이름 수정','editCategory',chosen)+' '+btn('카테고리 삭제','deleteCategory',chosen,'danger')+' '+btn('조항 추가','editRule'):''}</div>`:''}<div class="tabs">${cats.map(c=>btn(E(c.name),'category',c.id,chosen===c.id?'active':'')).join('')}</div><div class="stack">${rr.map((r,i)=>card(`제${i+1}조 · ${E(r.name)}`,`<p>위반 시 ${r.lumen}루멘 · ${r.xp}XP 차감</p><div class="section">${report||T()?btn('학생 선택 · 위반 등록','violate',r.id,'primary'):''} ${T()?btn('수정','editRule',r.id,'small')+' '+btn('삭제','deleteRule',r.id,'small danger'):''}</div>`)).join('')||empty('이 카테고리에 조항이 없어요.')}</div>`}
function citizenSummary(){let c=state.citizens.find(c=>c.status!=='archived');return c?`<p class="large gold">${c.status==='active'?'진행 중':c.status==='paid'?'지급 완료':'종료'}</p><p>${fmt(c.start)} ~ ${c.end?fmt(c.end):''}</p><p class="hint">보상 ${c.reward[0]}루멘 · ${c.reward[1]}XP</p>`:'<p>새 회차를 준비하고 있어요.</p>'}
function citizenPage(){let c=state.citizens.find(c=>c.status!=='archived');return card('모범시민',citizenSummary()+`${T()?`<div class="flex section">${!c?btn('진행 시작','citizenStart','','primary'):c.status==='active'?btn('종료','citizenEnd','','primary'):btn('보상 지급','citizenPay','','primary')}${c?btn('회차 초기화','citizenReset','','danger'):''}</div>`:c?.end?`<div class="note">${c.eligible?'이번 회차 보상 대상이에요.':'이번 회차는 아쉽지만, 다음 회차에 다시 도전해요.'} ${c.paid?'보상 지급 완료 ✓':''}</div>`:''}`)+`${T()&&c?.end?card('보상 대상 확인',table(['학생','대상 여부','교사 정정'],active().map(p=>[E(p.name),c.eligible.includes(p.id)?'대상 ✓':'제외',btn(c.eligible.includes(p.id)?'제외':'포함','citizenOverride',p.id,'small')]))):''}`+card(T()?'위반 기록':'이번 회차 내 위반 기록',table(['시각','학생','조항','차감','상태'],state.violations.slice().reverse().map(v=>[fmt(v.time),E(name(v.student)),`${E(v.category)} 제${v.number}조<div class="muted">${E(v.name)}</div>`,`${v.lumen}루멘 / ${v.xp}XP`,v.cancelled?'취소':T()?btn('취소','reverse',v.ledger,'small danger'):'등록'])))}
function messagesPage(){let th=find(state.threads,selectedThread);return `<div class="grid cols2">${card(T()?'학생 메시지':'나의 대화',`${!T()?btn('새 메시지','newMessage','','primary'):''}<div class="stack section">${state.threads.slice().reverse().map(t=>`<button class="tile" data-action="thread" data-id="${t.id}"><strong>${E(t.title)}</strong><p>${T()?E(name(t.student))+' · ':''}${t.closed?'대화 완료':t.lastBy==='teacher'?'선생님 답장':'학생 메시지'} · ${fmt(t.messages.at(-1).time)}</p></button>`).join('')||empty('아직 대화가 없어요.')}</div>`)}${card(th?E(th.title):'대화 내용',th?`${T()?btn(th.closed?'다시 열기':'대화 완료','closeThread',th.id,'small'):''}<div class="conversation">${th.messages.map(m=>`<div class="bubble ${m.by===state.actor?'mine':''}">${E(m.body)}<span class="time">${m.by==='teacher'?'선생님':E(name(th.student))} · ${fmt(m.time)}</span></div>`).join('')}</div>${th.closed?'<p>완료된 대화예요. 내용은 계속 볼 수 있어요.</p>':`<form id="reply-form">${area('답장','body',replyDrafts[th.id]||'')}<div class="section"><button type="submit" class="primary">답장 보내기</button></div></form>`}`:empty('대화를 선택해 주세요.'))}</div>`}
function settingsPage(){return `<div class="grid cols2">${card('학급 운영',`<p>${E(state.className)}</p><div class="flex section">${btn(state.opened?'학생 접속 잠시 닫기':'학급 시작 · 접속 열기','toggleOpen','','primary')}${btn('학급 이름','className')}${btn('교사 비밀번호 변경','teacherPassword')}</div>`)}${card('보상 · 등급 설정',`<p>진행 중인 보상은 유지하고 변경 사항은 정해진 다음 기간부터 적용해요.</p><div class="flex section">${btn('등급 기준','ranks')}${btn('아침·독서 보상','activityRewards')}</div>`)}</div>${card('수동 백업 · 복원',`<p>교사 컴퓨터에 현재 시점의 전체 자료를 저장해요. 자동 백업은 하지 않아요.</p><div class="flex section">${btn('백업 내려받기','backup','','primary')}${btn('파일에서 복원','restore')}</div><input id="backup-file" type="file" accept=".json" hidden><div class="note">복원하면 현재 자료가 백업 시점으로 바뀌어요. 학생 접속은 닫히고 다시 로그인해야 해요.</div>`)}${card('새 학년도 시작',`<p>학생과 모든 기록을 비워요. 교사 설정과 상품은 유지하고 재고는 0으로 바꿔요.</p><div class="section">${btn('새 학년도 초기화','newYear','','danger')}</div>`,'danger-zone')}`}
function content(){switch(page){case'home':return home();case'students':return studentsPage();case'points':return pointsPage();case'history':return card('루멘 · XP 변동 내역',historyTabs()+ledger(historyStudent||state.actor));case'pocket':return card('나의 주머니',pocket());case'morning':case'reading':return activityPage(page);case'activities':return activitiesPage();case'shop':return shopPage();case'delivery':return deliveryPage();case'bank':return bankPage();case'thermo':return thermoPage();case'jobs':return jobsPage();case'quests':return questsPage();case'laws':return lawsPage();case'report':return lawsPage(true);case'penalties':case'citizen':return citizenPage();case'messages':return messagesPage();case'schedule':return card('일정 · 급식 입력',`<form id="schedule-form">${field('날짜','date','date',today(),'required')}${area('일정','events',state.schedule[today()]?.events||'')}${area('급식','meal',state.schedule[today()]?.meal||'')}<div class="section"><button class="primary" type="submit">저장</button></div></form>`);case'settings':return settingsPage();default:return empty('메뉴를 선택해 주세요.')}}
async function action(act,id){let f,p,r,c;switch(act){
case'jobPick':jobPicked=jobPicked===id?null:id;paintJobBoard();return;
case'jobDrop':placeJob(id);return;
case'menu':$('.sidebar').classList.toggle('open');return;
case'changePin':f=await modal('나의 PIN 변경',field('새 PIN (숫자 4~8자리)','pin','password','','required pattern="[0-9]{4,8}"'));if(f)return command('pin',f);return;
case'logout':return logout();case'go':page=id==='xpHistory'?'history':id;if(id==='history'||id==='xpHistory')historyCurrency=id==='xpHistory'?'xp':'lumen';selected.clear();historyStudent=null;render();return;
case'select':selected.has(id)?selected.delete(id):selected.add(id);render();return;
case'selectAll':selected=new Set(active().map(p=>p.id));render();return;case'clearSelect':selected.clear();render();return;
case'read':return command('read');
case'characters':{let rank=atRank(me());await modal('지금 등급의 친구를 골라요',`<p>등급이 바뀌면 공통 알로 돌아가 다시 선택할 수 있어요.</p><div class="grid cols2 section">${['용','그리핀','불사조','바다 괴수'].map((label,i)=>`<button type="button" data-action="chooseCharacter" data-id="${rank}-${i}">${creature({character:rank+'-'+i})}<p>${label}</p></button>`).join('')}</div>`,'',true);return;}
case'chooseCharacter':$('#dialog').close();return command('character',{value:id});
case'roster':f=await modal('명단 붙여넣기',`<p>한 줄에 번호와 이름을 입력해 주세요. 예: 1 김민서</p>${area('명단','roster')}`,'미리보기');if(!f)return;{let rows=f.roster.trim().split('\n').filter(Boolean).map(line=>{let m=line.trim().match(/^(\d+)[\s,\t]+(.+)$/);if(!m)throw Error('각 줄을 “1 김민서” 형식으로 입력해 주세요.');return {number:+m[1],name:m[2].trim()}});if(new Set(rows.map(r=>r.number)).size!==rows.length)throw Error('명단 안에 중복 번호가 있어요.');if(await confirmBox('명단 확인',table(['번호','이름'],rows.map(r=>[r.number,E(r.name)]))))return command('roster',{rows});}return;
case'addStudent':f=await modal('학생 추가',field('번호','number','number','','min="1" required')+field('이름','name','text','','required'));if(f)return command('roster',{rows:[{number:+f.number,name:f.name}]});return;
case'editStudent':p=find(state.students,id);f=await modal('학생 정보',field('이름','name','text',p.name,'required')+select('상태','active',[['yes','활동 중'],['no','전출 · 접속 차단']],p.active?'yes':'no'));if(f)return command('student',{id,name:f.name,active:f.active==='yes'});return;
case'resetPin':if(await confirmBox('임시 PIN 재발급','<p>현재 로그인이 종료되고 첫 로그인 때 PIN을 다시 변경해야 해요.</p>'))return command('resetPin',{id});return;
case'studentDetail':historyStudent=id;p=find(state.students,id);await modal(E(p.name)+' · 학생 상세',`<div class="flex">${btn('최근 독서 30건','readingHistory',id,'small')}</div>${historyTabs()}${ledger(id)}`,'',true);return;
case'historyCurrency':historyCurrency=id;if(T()&&historyStudent)return action('studentDetail',historyStudent);render();return;
case'readingHistory':await modal(E(name(id))+' · 최근 독서',table(['날짜','책','쪽','읽은 쪽수'],state.activities.filter(r=>r.student===id&&r.kind==='reading').slice(-30).reverse().map(r=>[r.date,E(r.title),r.start+'~'+r.end,r.end-r.start+1])),'',true);return;
case'points':if(!selected.size)throw Error('먼저 학생을 선택해 주세요.');f=await modal('루멘 · XP 조정',`<p>${[...selected].map(x=>E(name(x))).join(', ')} · ${selected.size}명</p><div class="grid cols2">${field('루멘 (차감은 음수)','lumen','number',0,'required')}${field('XP (차감은 음수)','xp','number',0,'required')}</div>${field('사유 (선택)','reason')}`,'내용 확인');if(f&&await confirmBox('지급 · 차감 확정',`<p>${selected.size}명에게 각각 <strong>${+f.lumen}루멘 · ${+f.xp}XP</strong>를 반영할까요?</p>`))return command('points',{students:[...selected],lumen:+f.lumen,xp:+f.xp,reason:f.reason});return;
case'reverse':if(await confirmBox('해당 거래 취소','<p>이 거래의 실제 금액만 되돌리고 이후 다른 거래는 유지해요. XP는 0 아래로 내려가지 않아요.</p>'))return command('reverse',{id});return;
case'repay':if(await confirmBox('취소한 보상 재지급','<p>원래 보상량을 다시 지급해요. 이미 유효한 보상이 있으면 중복 지급하지 않아요.</p>'))return command('repay',{id});return;
case'shopCategory':shopCategory=id;render();return;
case'editProduct':p=find(state.products,id)||{name:'',price:0,stock:0,image:8,category:'간식',description:'',active:false};f=await modal(id?'상품 수정':'상품 추가',field('상품 이름','name','text',p.name,'required maxlength="60"')+select('분류','category',['간식','문구','쿠폰','특별'].map(x=>[x,x]),productCategory(p))+productPicker(p.image)+`<div class="grid cols2">${field('가격 (루멘)','price','number',p.price,'min="0" max="1000000" required')}${field('재고','stock','number',p.stock,'min="0" max="1000000" required')}</div>`+area('상품 설명 (선택)','description',p.description||'')+select('판매 상태','active',[['no','판매 준비 · 학생에게 숨김'],['yes','판매 중']],p.active?'yes':'no'),'저장',true);if(f){if(f.active==='yes'&&+f.price===0&&!await confirmBox('무료 상품 확인','<p>가격이 0루멘입니다. 무료 상품으로 판매할까요?</p>'))return;return command('product',{...f,id:id||undefined,price:+f.price,stock:+f.stock,image:+f.image,active:f.active==='yes'});}return;
case'buy':p=find(state.products,id);{let price=state.discounts[today()]===id?Math.floor((p.price*85+50)/100):p.price;if(await confirmBox('상품 구매',`<p><strong>${E(p.name)} · ${price}루멘</strong></p><div class="note">구매 후 환불할 수 없어요. 주머니에 담긴 물건은 직접 지급 요청을 눌러 주세요.</div>`))return command('buy',{id,price},'주머니에 담았어요.');}return;
case'request':return command('request',{id},'상인에게 지급을 요청했어요.');
case'deliver':if(await confirmBox('물건 지급 완료','<p>실제로 물건을 전달했나요? 확인하면 주머니에서 사라져요.</p>'))return command('deliver',{id});return;
case'delivered':await modal('완료된 지급',table(['학생','물건','지급 시각','정정'],state.items.filter(i=>i.status==='delivered').slice(-30).reverse().map(i=>[E(name(i.student)),E(i.name),fmt(i.deliveredAt),btn('지급 취소','undoDelivery',i.id,'small')])),'',true);return;
case'undoDelivery':f=await modal('잘못된 지급 정정',`<p>돈과 재고는 바뀌지 않고 동일한 물건을 주머니로 되돌려요. 빈 칸이 있어야 해요.</p>${field('정정 사유','reason','text','','required')}`);if(f)return command('undoDelivery',{id,...f});return;
case'deposit':f=await modal('예금 가입','<p>10일 뒤 원금과 3% 이자가 자동 지급돼요.</p>'+field('예금 금액','amount','number',100,'min="100" step="100" required'),'가입');if(f)return command('deposit',{amount:+f.amount});return;
case'withdraw':p=find(state.deposits,id);if(await confirmBox('예금 중도 해지',`<p>이자 없이 원금 <strong>${p.amount}루멘</strong>만 반환돼요.</p>`))return command('withdraw',{id});return;
case'donate':{let used=mine(state.donations).filter(d=>d.date===today()).reduce((a,d)=>a+d.amount,0),max=Math.max(0,Math.min(100-used,10000-state.thermo.total,me().lumen));if(!max)throw Error('오늘 기부 가능 금액이나 잔액을 확인해 주세요.');f=await modal('마음 모으기',`<p>오늘 최대 ${max}루멘을 기부할 수 있어요. 기부 후 취소·환불은 불가해요.</p>${field('기부할 루멘','amount','number',max,`min="1" max="${max}" required`)}`,'기부 확정');if(f)return command('donate',{amount:+f.amount});}return;
case'thermoEvents':f=await modal('단계별 이벤트',state.thermo.events.map((x,i)=>field((i+1)*20+'°C 이벤트','e'+i,'text',x,'required')).join(''));if(f)return command('thermo',{events:Array.from({length:5},(_,i)=>f['e'+i])});return;
case'thermoDone':return command('thermo',{stage:+id});
case'thermoReset':if(await confirmBox('온도계 새 회차','<p>누적 기부액과 이벤트 실행 상태를 비워요. 오늘 개인 기부 한도는 유지해요.</p>'))return command('thermo',{reset:true});return;
case'record':if(id==='morning')return command('activity',{kind:id});f=await modal('독서 기록',field('책 제목','title','text','','required')+`<div class="grid cols2">${field('시작 쪽','start','number',1,'min="1" required')}${field('마지막 쪽','end','number',10,'min="1" required')}</div>`);if(f)return command('activity',{kind:'reading',title:f.title,start:+f.start,end:+f.end});return;
case'selectRecorded':selected=new Set(state.activities.filter(r=>r.kind===activityKind&&r.date===(activityDate||today())).map(r=>r.student));render();return;
case'teacherRecord':f=await modal('누락 활동 기록 추가',select('학생','student',active().map(p=>[p.id,p.name]))+(activityKind==='reading'?field('책 제목','title','text','','required')+field('시작 쪽','start','number',1,'min="1" required')+field('마지막 쪽','end','number',10,'min="1" required'):''));if(f)return command('activity',{...f,kind:activityKind,date:activityDate||today(),start:+f.start,end:+f.end});return;
case'editReading':r=find(state.activities,id);f=await modal('독서 기록 수정',field('책 제목','title','text',r.title,'required')+field('시작 쪽','start','number',r.start,'min="1" required')+field('마지막 쪽','end','number',r.end,'min="1" required'));if(f)return command('activityEdit',{id,title:f.title,start:+f.start,end:+f.end});return;
case'closeActivity':if(await confirmBox('활동 마감 · 보상 지급',`<p>${activityDate||today()} · ${activityKind==='morning'?'아침 활동':'독서'}<br>${[...selected].map(x=>E(name(x))).join(', ')} (${selected.size}명)</p><p class="hint">마감 후 학생 기록은 잠겨요. 이미 지급된 보상은 중복 지급하지 않아요.</p>`))return command('closeActivity',{kind:activityKind,date:activityDate||today(),students:[...selected]});return;
case'editJob':p=find(state.jobs,id)||{name:'',checklist:[],reward:[20,10],active:true};f=await modal('직업 설정',field('직업 이름','name','text',p.name,'required')+area('체크리스트 (한 줄에 하나)','checklist',p.checklist.join('\n'))+rewardFields(p.reward)+select('사용 여부','active',[['yes','사용'],['no','비활성']],p.active?'yes':'no'));if(f)return command('job',{id:id||undefined,name:f.name,checklist:f.checklist.split('\n').map(x=>x.trim()).filter(Boolean),reward:numberFields(f),active:f.active==='yes'});return;
case'jobStart':jobDraft={};jobPicked=null;f=await modal('직업 배정 · 기간 시작',jobBoard(),'기간 시작',true);jobDraft=null;jobPicked=null;if(f)return command('jobStart',{assignments:Object.fromEntries(Object.entries(f).filter(([k,v])=>v))});return;
case'jobAssignment':p=state.jobPeriods.find(p=>p.status==='active');f=await modal('잘못된 직업 배정 정정',select('직업','job',Object.values(p.jobs).map(j=>[j.id,j.name]),p.assignments[id])+field('정정 사유','reason','text','','required'));if(f)return command('jobAssignment',{id:p.id,student:id,...f});return;
case'jobEnd':if(await confirmBox('직업 기간 종료','<p>학생 수행 기록을 닫고 교사 정산 단계로 넘어가요.</p>'))return command('jobEnd',{id});return;
case'jobAdjust':p=[...state.jobPeriods].reverse().find(p=>p.status==='ended');f=await modal(E(name(id))+' 인정일 정정',area('인정 날짜 (한 줄에 YYYY-MM-DD)','dates',(p.adjustments[id]||state.jobRecords.filter(r=>r.student===id&&r.period===p.id).map(r=>r.date)).join('\n'))+field('정정 사유','reason','text','','required'));if(f)return command('jobAdjust',{id:p.id,student:id,dates:f.dates.split('\n').map(x=>x.trim()).filter(Boolean),reason:f.reason});return;
case'jobPay':if(await confirmBox('직업 보상 정산','<p>학생별 인정일 × 기간 시작 당시의 보상량을 지급해요.</p>'))return command('jobPay',{id});return;
case'editQuest':p=find(state.quests,id)||{name:'',description:'',start:today(),end:today(),reward:[20,10]};f=await modal('퀘스트 만들기',field('제목','name','text',p.name,'required')+area('설명','description',p.description)+field('시작일','start','date',p.start,'required')+field('마감일','end','date',p.end,'required')+(id&&p.status!=='draft'?`<p class="note">공개된 보상 ${p.reward[0]}루멘 · ${p.reward[1]}XP는 유지됩니다.</p><input type="hidden" name="lumen" value="${p.reward[0]}"><input type="hidden" name="xp" value="${p.reward[1]}">`:rewardFields(p.reward)),id&&p.status!=='draft'?'수정 저장':'공개');if(f)return command('quest',{id:id||undefined,...f,reward:numberFields(f)});return;
case'questCopy':return command('quest',{id,action:'copy'});case'questEnd':return command('quest',{id,action:'ended'});case'questHide':return command('quest',{id,action:'hidden'});case'questDelete':if(await confirmBox('퀘스트 삭제','<p>신청 기록이 없는 퀘스트만 삭제할 수 있어요.</p>'))return command('quest',{id,action:'delete'});return;
case'applyQuest':return command('applyQuest',{id});case'approveQuest':if(await confirmBox('퀘스트 승인','<p>완료를 인정하고 설정된 보상을 지급할까요?</p>'))return command('reviewQuest',{id,approve:true});return;
case'rejectQuest':f=await modal('신청 반려',field('반려 사유','reason','text','','required'));if(f)return command('reviewQuest',{id,approve:false,...f});return;
case'category':category=id;render();return;
case'editCategory':f=await modal('카테고리',field('이름','name','text',find(state.categories,id)?.name||'','required'));if(f)return command('category',{id:id||undefined,...f});return;
case'deleteCategory':if(await confirmBox('카테고리 삭제',`<p>${E(find(state.categories,id).name)}와 조항 ${state.rules.filter(r=>r.category===id).length}개를 함께 삭제할까요? 과거 위반 기록은 남아요.</p>`)){category=null;return command('category',{id,delete:true})}return;
case'editRule':p=find(state.rules,id)||{name:'',category:category||state.categories[0]?.id,lumen:10,xp:0};if(!state.categories.length)throw Error('카테고리를 먼저 추가해 주세요.');f=await modal('법 조항',select('카테고리','category',state.categories.map(c=>[c.id,c.name]),p.category)+field('조항 내용','name','text',p.name,'required')+rewardFields([p.lumen,p.xp]));if(f)return command('rule',{id:id||undefined,...f,lumen:+f.lumen,xp:+f.xp});return;
case'deleteRule':if(await confirmBox('조항 삭제','<p>새 위반 등록 목록에서 제외돼요. 과거 기록은 유지해요.</p>'))return command('rule',{id,delete:true});return;
case'violate':p=find(state.rules,id);f=await modal(E(p.name),`<p>각 학생에게 ${p.lumen}루멘 · ${p.xp}XP가 즉시 차감돼요.</p><div class="select-grid section">${active().map(p=>`<label class="check-row"><input type="checkbox" name="s_${p.id}"><span>${p.number} ${E(p.name)}</span></label>`).join('')}</div>`,'위반 등록',true);if(f){let students=Object.keys(f).filter(k=>k.startsWith('s_')).map(k=>k.slice(2));if(!students.length)throw Error('학생을 선택해 주세요.');return command('violate',{rule:id,students})}return;
case'citizenStart':f=await modal('모범시민 진행 시작',rewardFields(state.citizenReward),'시작');if(f)return command('citizen',{action:'start',reward:numberFields(f)});return;
case'citizenEnd':if(await confirmBox('모범시민 종료','<p>현재 시각으로 집계를 마감하고 보상 대상을 확인해요.</p>'))return command('citizen',{action:'end'});return;
case'citizenPay':c=state.citizens.find(c=>c.status!=='archived');if(await confirmBox('모범시민 보상 지급',`<p>대상 ${c.eligible.length}명 · 각각 ${c.reward[0]}루멘 / ${c.reward[1]}XP</p><p>이미 유효한 보상을 받은 학생은 제외하고 지급해요.</p>`))return command('citizen',{action:'pay'});return;
case'citizenReset':if(await confirmBox('모범시민 회차 초기화','<p>학생 화면의 지난 위반과 결과가 지워져요. 잔액과 교사 기록은 유지해요. 아직 지급하지 않은 보상이 있으면 먼저 지급해 주세요.</p>'))return command('citizen',{action:'reset'});return;
case'citizenOverride':c=state.citizens.find(c=>c.status!=='archived');f=await modal('보상 대상 정정',`<p>${E(name(id))} 학생을 ${c.eligible.includes(id)?'제외':'포함'}해요.</p>`+field('사유','reason','text','','required'));if(f)return command('citizen',{action:'override',student:id,include:!c.eligible.includes(id),reason:f.reason});return;
case'newMessage':f=await modal('선생님께 메시지',field('제목','title','text',messageDraft.title,'required maxlength="100"')+area('내용','body',messageDraft.body),'보내기');if(f){messageDraft=f;if(await command('message',f))messageDraft={title:'',body:''};else if(token)toast('전송하지 못했어요. 새 메시지를 다시 열면 작성한 글이 남아 있어요.');}return;
case'thread':selectedThread=id;render();return;case'closeThread':p=find(state.threads,id);return command('thread',{id,closed:!p.closed});
case'toggleOpen':if(await confirmBox(state.opened?'학생 접속 닫기':'학생 접속 열기',`<p>${state.opened?'접속 중인 학생도 로그아웃돼요.':'등록된 학생이 로그인할 수 있어요.'}</p>`))return command('open',{value:!state.opened});return;
case'className':f=await modal('학급 이름',field('이름','className','text',state.className,'required'));if(f)return command('settings',f);return;
case'teacherPassword':f=await modal('교사 비밀번호 변경',field('새 비밀번호','password','password','','minlength="8" required'),'변경 후 다시 로그인');if(f){await command('settings',f);return logout(false)}return;
case'ranks':f=await modal('5개 등급 설정',state.ranks.map((r,i)=>`<div class="grid cols2">${field((i+1)+'등급 이름','name'+i,'text',r.name,'required')}${field('필요 XP','xp'+i,'number',r.xp,'min="0" required')}</div>`).join(''));if(f)return command('settings',{ranks:Array.from({length:5},(_,i)=>({name:f['name'+i],xp:+f['xp'+i]}))});return;
case'activityRewards':p=state.rewardSchedule.at(-1);f=await modal('아침 · 독서 보상','<p>변경 값은 내일부터 적용돼요. 오늘 보상은 유지해요.</p><h3 class="section">아침 활동</h3>'+field('루멘','ml','number',p.morning[0],'min="0" required')+field('XP','mx','number',p.morning[1],'min="0" required')+'<h3 class="section">독서</h3>'+field('루멘','rl','number',p.reading[0],'min="0" required')+field('XP','rx','number',p.reading[1],'min="0" required'));if(f)return command('settings',{morning:[+f.ml,+f.mx],reading:[+f.rl,+f.rx]});return;
case'backup':{const data=await api('backup'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`SEBIT-backup-${today()}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 내려받았어요.');}return;
case'restore':$('#backup-file').click();return;
case'newYear':f=await modal('새 학년도 초기화',`<div class="note">학생과 모든 활동·거래·메시지를 지워요. 필요하면 먼저 수동 백업해 주세요. 설정은 유지하고 상품 재고는 0이 돼요.</div>${field('확인을 위해 학급 이름 입력','confirm','text','','required')}`,'초기화');if(f)return command('newYear',f);return;
}}
document.addEventListener('click',async e=>{let nav=e.target.closest('[data-nav]'),b=e.target.closest('[data-action]');try{if(nav){page=nav.dataset.nav;studentSearch='';selected.clear();historyStudent=null;render();return}if(b)await action(b.dataset.action,b.dataset.id)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(!token)return;if(e.target.id==='student-search'){studentSearch=e.target.value.trim();document.querySelectorAll('[data-student-label]').forEach(b=>b.hidden=!b.dataset.studentLabel.includes(studentSearch));}if(e.target.closest('#reply-form')&&selectedThread)replyDrafts[selectedThread]=e.target.value;if(e.target.closest('#modal-form')&&$('#modal-form [name=title]')&&['title','body'].includes(e.target.name))messageDraft[e.target.name]=e.target.value;});
document.addEventListener('change',async e=>{if(e.target.id==='activity-date'){activityDate=e.target.value;selected.clear();render()}if(e.target.id==='activity-kind'){activityKind=e.target.value;selected.clear();render()}if(e.target.id==='backup-file'){try{let file=e.target.files[0];if(!file)return;if(file.size>26000000)throw Error('백업 파일이 너무 커요.');let backup=JSON.parse(await file.text());if(backup.format!=='SEBIT-1')throw Error('SEBIT 백업 파일이 아니에요.');let f=await modal('백업 복원 확인',`<p>학급: ${E(backup.className)}<br>저장: ${fmt(backup.savedAt)}<br>학생: ${backup.state.students.length}명</p><div class="note">현재 자료 전체가 이 시점으로 바뀌어요. 복원 전 자동 백업은 하지 않아요.</div>${field('백업의 학급 이름을 입력','confirm','text','','required')}`,'복원');if(f){await api('restore',{backup,confirm:f.confirm});toast('복원했어요. 학생 접속은 닫혀 있어요.');await logout(false)}}catch(err){toast(err.message)}}if(e.target.closest('#schedule-form')&&e.target.name==='date'){let v=state.schedule[e.target.value]||{};$('[name=events]').value=v.events||'';$('[name=meal]').value=v.meal||'';}});
document.addEventListener('submit',async e=>{try{if(e.target.id==='job-complete'){e.preventDefault();let fd=new FormData(e.target);await command('jobComplete',{checks:fd.getAll('check').map(Number),memo:fd.get('memo')})}if(e.target.id==='reply-form'){e.preventDefault();const thread=selectedThread,body=new FormData(e.target).get('body');replyDrafts[thread]=body;if(await command('message',{id:thread,body})){delete replyDrafts[thread];if(token)render();}}if(e.target.id==='schedule-form'){e.preventDefault();await command('schedule',Object.fromEntries(new FormData(e.target)))}}catch(err){toast(err.message)}});
for(const event of ['pointerdown','keydown','input'])document.addEventListener(event,()=>{lastActivity=Date.now();if(token&&Date.now()-lastTouch>30000){lastTouch=Date.now();api('touch',{}).catch(()=>{});}},{passive:true});
setInterval(async()=>{if(!token||!state)return;const idle=Date.now()-lastActivity;if(!T()&&idle>=180000){await logout();toast('3분 동안 조작이 없어 로그아웃되었어요.');return}if(!T()&&idle>=150000&&!$('#dialog').open){const f=await modal('계속 사용하고 있나요?','<p>30초 뒤 자동 로그아웃돼요.</p>','계속 사용');if(f){lastActivity=Date.now();await api('touch',{})}}},1000);
setInterval(()=>{if(!document.hidden&&token&&state&&!busy&&!$('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))refresh();},15000);
start();
